"""Read-only local authoring board for the frozen 462 dossiers, not the product GUI."""
from pathlib import Path
from collections import Counter
import argparse,hashlib,importlib.util,json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'EXPEDIENTES-462';DATA=ROOT/'development/hardware/selection462'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def build():
 manifest=read(DATA/'manifest.json');rows=[]
 if manifest['counts']['officialRecords']!=11:raise ValueError('official_phase_not_complete')
 for rel,pin in {**manifest['inputs'],**manifest['files']}.items():
  if sha(ROOT/rel)!=pin:raise ValueError('source_stale')
 for i in range(1,4):rows+=read(DATA/f'part-{i:02}.json')['models']
 if len(rows)!=462 or len({m['selectionId']for m in rows})!=462:raise ValueError('selection_union_invalid')
 display=dict(counts=manifest['counts'],models=rows)
 raw=json.dumps(display,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('<','\\u003c').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
 html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RackClick · preparación de 462 modelos</title><link rel="stylesheet" href="EXPEDIENTES-462/view.css"><body><header><h1>Preparación de la selección original</h1><p id="counts"></p><p class="warning">Expedientes de fuentes. No son 462 carcasas terminadas ni perfiles instalables. No se crean equipos ni cables desde esta página.</p><a href="docs/COBERTURA-MODELOS-ELEGIDOS.md">Cobertura de perfiles</a> · <a href="docs/PREPARACION-SELECCION-462.md">Registro y siguiente trabajo</a> · <button id="csv">Descargar índice CSV</button></header><section class="controls"><label>Buscar fabricante, modelo o ID <input id="search" type="search"></label><label>Categoría <select id="category"><option value="">Todas</option></select></label><label>Fuente de datos <select id="source"><option value="">Todas</option><option value="community">YAML comunitario</option><option value="official">Sólo fuentes oficiales</option></select></label><p id="found"></p><button id="previous">Anterior</button> <span id="page"></span> <button id="next">Siguiente</button></section><main><nav id="models" aria-label="Modelos seleccionados"></nav><article id="detail"></article></main><script src="EXPEDIENTES-462/data.js"></script><script src="EXPEDIENTES-462/view.js"></script></body></html>'''
 js='''(()=>{'use strict';const D=window.RACKCLICK_SELECTED_DATA,all=D.models,byId=new Map(all.map(m=>[m.selectionId,m]));let page=0,selected=all[0].selectionId;const size=25,$=s=>document.querySelector(s),node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=String(text);if(cls)n.className=cls;return n};const labels={switch:'Switches',firewall:'Firewalls',router:'Routers',nas:'NAS',ap:'Puntos de acceso',rack:'Racks',shelf:'Bandejas',pdu:'PDU',ups:'UPS / SAI',server:'Servidores',storage:'Almacenamiento',other:'Otros equipos','patch-panel':'Patch panels'};const norm=s=>String(s||'').normalize('NFKC').toLocaleLowerCase('es');
$('#counts').textContent=all.length+' expedientes · '+D.counts.exactCommunityYaml+' YAML exactos · '+D.counts.officialRecords+' expedientes oficiales adicionales · 0 geometrías completas nuevas · 0 perfiles promovidos';for(const c of [...new Set(all.map(m=>m.category))].sort()){const o=node('option',labels[c]||c);o.value=c;$('#category').append(o)}
function matching(){const q=norm($('#search').value),cat=$('#category').value,s=$('#source').value;return all.filter(m=>norm([m.selectionId,...Object.values(m.identity)].join(' ')).includes(q)&&(!cat||m.category===cat)&&(!s||m.sourceRecords.some(r=>r.kind==='community_yaml')===(s==='community')))}
function renderList(){const list=matching();page=Math.max(0,Math.min(page,Math.ceil(list.length/size)-1));$('#models').replaceChildren();for(const m of list.slice(page*size,(page+1)*size)){const b=node('button',m.identity.manufacturer+' · '+m.identity.model);b.dataset.id=m.selectionId;b.classList.toggle('selected',selected===m.selectionId);b.onclick=()=>{selected=m.selectionId;renderList();renderDetail()};$('#models').append(b)}$('#found').textContent=list.length+' modelos encontrados';$('#page').textContent=(page+1)+' / '+Math.max(1,Math.ceil(list.length/size));$('#previous').disabled=page===0;$('#next').disabled=(page+1)*size>=list.length}
function panel(title){const s=node('section');s.append(node('h3',title));$('#detail').append(s);return s}function pair(s,k,v){s.append(node('p',k+': '+(v===null||v===undefined?'Sin verificar':v)))}
function renderDetail(){const m=byId.get(selected),box=$('#detail');box.replaceChildren();box.dataset.id=m.selectionId;box.append(node('h2',m.identity.manufacturer+' · '+m.identity.model));box.append(node('p',m.selectionId+' · '+(labels[m.category]||m.category)));const state=panel('Estado real');state.append(node('p','Fuentes preparadas. Geometría, creación, montaje y cableado funcional pendientes.','warning'));pair(state,'Promoción',m.promotion.status);pair(state,'SKU',m.identity.sku);pair(state,'Revisión física',m.identity.hardwareRevision);
const dims=panel('Cotas y montaje documentados');for(const[k,v]of Object.entries(m.facts.dimensionsMm))pair(dims,k+' (mm)',v);for(const[k,v]of Object.entries(m.facts.mounting))pair(dims,k,v);dims.append(node('p','Las cotas informadas no certifican pies, accesorios, carga, ventilación ni compatibilidad de instalación.'));
const views=panel('Referencias visuales · sin geometría operativa');for(const face of ['front','rear']){const section=node('section'),v=m.visual[face];section.append(node('h4',face==='front'?'Frontal':'Trasera'));section.append(node('p',v.referenceAssets.length?'Imágenes de referencia; no acreditan posiciones ni exactitud de una configuración.':'No hay vista directa asignada y verificada.'));for(const a of v.referenceAssets){const img=node('img');img.loading='lazy';img.alt=(face==='front'?'Referencia frontal: ':'Referencia trasera: ')+m.identity.model;img.src=a.path;img.onerror=()=>{img.replaceWith(node('p','Referencia privada no disponible en esta copia: '+a.path))};section.append(img);section.append(node('p','Alcance de fuente: '+a.scope))}views.append(section)}
const facts=panel('Declaraciones de componentes · no son extremos instalados');for(const[k,v]of Object.entries(m.facts)){if(!Array.isArray(v)&&!['officialDeclarations','sourceComments'].includes(k))continue;const d=node('details');d.append(node('summary',k+(Array.isArray(v)?' · '+v.length+' registros declarados':'')));d.append(node('p','Una lista vacía no demuestra ausencia física. Los módulos y puertos opcionales no se materializan.'));d.append(node('pre',typeof v==='string'?v:JSON.stringify(v,null,2)));facts.append(d)}
const unknown=panel('Lo que falta para terminar este perfil');const ul=node('ul');for(const u of m.unknowns)ul.append(node('li',u.path+' — '+u.reason));unknown.append(ul);
const sources=panel('Procedencia y afirmaciones por campo');for(const s of m.sourceRecords){const d=node('details');d.append(node('summary',s.id+' · '+s.kind+' · '+s.scope));if(typeof s.url==='string'&&s.url.startsWith('https://')){const a=node('a','Abrir fuente');a.href=s.url;a.target='_blank';a.rel='noopener noreferrer';d.append(a)}d.append(node('pre',JSON.stringify(s,null,2)));sources.append(d)}const c=node('details');c.append(node('summary',m.claims.length+' vínculos campo → fuente'));c.append(node('pre',JSON.stringify(m.claims,null,2)));sources.append(c)}
for(const s of ['#search','#category','#source'])$(s).addEventListener('input',()=>{page=0;renderList()});$('#previous').onclick=()=>{page--;renderList()};$('#next').onclick=()=>{page++;renderList()};$('#csv').onclick=()=>{const esc=x=>'"'+String(x??'').replaceAll('"','""')+'"',lines=[['ID','Fabricante','Modelo','Categoria','Estado'].map(esc).join(','),...all.map(m=>[m.selectionId,m.identity.manufacturer,m.identity.model,m.category,'preparado; geometria y promocion pendientes'].map(esc).join(','))];const u=URL.createObjectURL(new Blob(['\\ufeff'+lines.join('\\r\\n')],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=u;a.download='RackClick-Expedientes-462.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)};window.RACKCLICK_SELECTED_VIEW={count:all.length,select(id){if(!byId.has(id))throw Error('unknown_model');selected=id;renderList();renderDetail()}};renderList();renderDetail();})();'''
 css='''body{margin:0;background:#111a22;color:#e4edf3;font:15px system-ui}header,.controls{padding:18px 24px;border-bottom:1px solid #405363}h1{margin:0 0 10px}h2{color:#28d9b0}a{color:#60d7f5}button,input,select{font:inherit;color:inherit;background:#1e303e;border:1px solid #526a7d;border-radius:5px;padding:8px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.warning{padding:12px;background:#413016;border:1px solid #aa8148}.controls label{display:inline-block;margin:0 14px 12px 0}input{min-width:280px}main{display:grid;grid-template-columns:300px minmax(0,1fr);gap:20px;padding:20px}nav button{display:block;text-align:left;width:100%;margin-bottom:8px}nav button.selected{border-color:#00dbab;background:#12483d}article{min-width:0}section section,article>section{border:1px solid #3c5060;padding:14px;margin:14px 0}img{display:block;max-width:100%;max-height:280px;background:#fff}details{padding:10px;border-bottom:1px solid #3c5060}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}li{margin:8px 0;overflow-wrap:anywhere}summary{cursor:pointer}@media(max-width:800px){main{grid-template-columns:1fr}nav{max-height:250px;overflow:auto}input{min-width:200px}}'''
 return {ROOT/'VER-EXPEDIENTES-462.html':html.encode('utf-8'),OUT/'data.js':('window.RACKCLICK_SELECTED_DATA='+raw+';\n').encode('utf-8'),OUT/'view.js':js.encode('utf-8'),OUT/'view.css':css.encode('utf-8')},manifest
def main():
 p=argparse.ArgumentParser(description=__doc__);g=p.add_mutually_exclusive_group(required=True);g.add_argument('--write',action='store_true');g.add_argument('--check',action='store_true');a=p.parse_args();files,source=build()
 files[OUT/'manifest.json']=(json.dumps(dict(kind='reference_authoring_board_not_installer',models=462,sourceManifestSha256=sha(DATA/'manifest.json'),files={p.relative_to(ROOT).as_posix():hashlib.sha256(b).hexdigest()for p,b in files.items()}),indent=2)+'\n').encode()
 for path,content in files.items():
  if a.write:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(content)
  elif not path.exists()or path.read_bytes()!=content:raise ValueError('view_stale:'+path.name)
 print(json.dumps(dict(result='written'if a.write else'checked',models=462,productChanged=False,geometryCompleted=0)))
if __name__=='__main__':main()
